#!/usr/bin/env python3
"""Render the recorded current-reader comparison as Markdown, CSV and HTML."""
import argparse,csv,html,json,pathlib,statistics
ROOT=pathlib.Path(__file__).resolve().parents[1]
p=argparse.ArgumentParser();p.add_argument('--evidence',type=pathlib.Path,default=ROOT/'docs/evidence/reader-benchmark');p.add_argument('--html',type=pathlib.Path,default=ROOT.parent/'output/libtiff-benchmark.html');a=p.parse_args()
data=json.loads((a.evidence/'results.json').read_text());layout=json.loads((a.evidence/'layout-results.json').read_text());defaults=json.loads((a.evidence/'defaults-results.json').read_text());records=data['records'];meta=data['metadata']
assert len(records)==78 and len({r['case']['name'] for r in records})==36
assert all(len(r['samples'][e])==7 and len(r['memory_samples'][e])==3 for r in records for e in ['verified','libtiff'])
def number(v):return f'{v:.4f}' if v<1 else f'{v:.3f}' if v<10 else f'{v:.2f}'
def ratio(v):return f'{v:.1f}× slower' if v>=1 else f'{1/v:.1f}× faster'
def table(headers,rows):return '| '+' | '.join(headers)+' |\n| '+' | '.join(['---']*len(headers))+' |\n'+''.join('| '+' | '.join(map(str,r))+' |\n' for r in rows)
def htable(headers,rows,ident=''):
 return '<div class="scroll"><table'+(' id="'+ident+'"' if ident else '')+'><thead><tr>'+''.join('<th>'+html.escape(h)+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(str(c))+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
summary=[]
for mode,label in [('native','Native strips / tiles'),('scan','Sequential scanlines'),('rgba','Full RGBA'),('crop','Centered 128 × 128 RGBA crop')]:
 values=[r['ratio'] for r in records if r['mode']==mode];summary.append([label,len(values),ratio(statistics.geometric_mean(values))])
selected=[('rgb-deflate','native'),('webp-lossless','native'),('webp-lossy','native'),('lerc-float-plain','native'),('lerc-float-deflate','native'),('lerc-float-zstd','native'),('large-strip-none','crop'),('large-strip-lzw','crop'),('large-strip-deflate','crop'),('large-strip-deflate','firstrow')]
representative=[]
for name,mode in selected:
 r=next(r for r in records if r['case']['name']==name and r['mode']==mode);s=r['statistics'];representative.append([r['case']['label'],mode,number(s['verified']['median_ms']),number(s['libtiff']['median_ms']),ratio(r['ratio'])])
layoutrows=[[r['rows_per_strip'],r['decoded_strip_kib'],r['mode'],number(r['statistics']['verified']['median_ms']),number(r['statistics']['libtiff']['median_ms']),ratio(r['ratio'])] for r in layout['records']]
memory=[]
for name,mode in [('large-strip-none','crop'),('large-strip-lzw','crop'),('large-strip-deflate','crop'),('original-lzw-single-strip.tiff','rgba'),('original-testfax4.tiff','rgba')]:
 r=next(r for r in records if r['case']['name']==name and r['mode']==mode);s=r['statistics'];memory.append([r['case']['label'],mode,number(s['verified']['median_rss_mib']),number(s['libtiff']['median_rss_mib'])])
defaultrows=[[r['case']['label'],r['mode'],number(r['statistics']['verified']['median_ms']),number(r['statistics']['libtiff']['median_ms']),ratio(r['ratio']),number(r['statistics']['verified']['median_rss_mib']),number(r['statistics']['libtiff']['median_rss_mib'])] for r in defaults['records']]
allrows=[]
for r in records:
 s=r['statistics'];v=s['verified'];b=s['libtiff'];allrows.append([r['case']['name'],r['mode'],number(v['median_ms']),number(b['median_ms']),ratio(r['ratio']),f"{number(v['q1_ms'])}–{number(v['q3_ms'])}",f"{number(b['q1_ms'])}–{number(b['q3_ms'])}",number(v['median_rss_mib']),number(b['median_rss_mib'])])
headers=['Workload','Operation','Verified ms','4.7.1 ms','Relative time','Verified IQR ms','4.7.1 IQR ms','Verified RSS MiB','4.7.1 RSS MiB']
intro='The current verified-tiff C reader is substantially slower than libtiff 4.7.1 on this suite: 13.3× as long for full native reads and 17.7× for full RGBA reads. The strongest benefits are lower memory for large compressed crops and lazy access to large strip tables. Streaming compressed reads, LERC float reconstruction, and RGBA conversion are the largest measured bottlenecks.'
scope='Measured 2026-10-15: 36 inputs, 78 API workloads, seven timing batches per engine/workload, and three separate peak-RSS processes per engine/workload. Eight additional strip-layout workloads, six default-strip-chopping workloads, and three diagnostic CPU profiles are recorded separately. All 14 supplementary output checks also passed exactly. All 78 output checks passed: 76 matched byte-for-byte; the two textured-JPEG operations differed by at most one 8-bit channel value (the allowed bound was three). Timed and memory-run output hashes matched their preflight results.'
methods=[
 'Both implementations use the same freshly compiled C consumer and the same TIFF inputs. Every timed operation opens a fresh handle, reads, and closes it; no decoded image or segment cache survives an operation. Native means all encoded strips/tiles in stored sample form, including native float/complex words and tile padding. RGBA means TIFFReadRGBAImageOriented; crops use TIFFRGBAImageBegin/Get/End with centered offsets.',
 'Timing uses identical in-memory callbacks with mmap and strip chopping disabled (mode rmc). Input loading, caller-output allocation, process startup, output hashing, fixture encoding, and correctness comparison are outside the timer. Internal library allocations, validation, conversion, and close are inside. One warm-up/calibration operation precedes batches of at least 100 ms, or a complete operation if longer. Engine order is shuffled reproducibly; processes run serially pinned to logical CPU 0. These are warm-cache measurements on a shared AMD EPYC 9V74 virtual host, not cold-storage or isolated-hardware measurements.',
 'Peak RSS is the median of three separate file-backed processes with mmap disabled, read from /proc/self/status VmHWM before hashing. It includes executable/runtime state, metadata setup, caller buffers, and library allocations; it is not exact library heap usage. RSS baselines differ between binaries. File-backed RSS runs are separate from the in-memory timing runs.',
 'The adapter is rebuilt in Cargo release mode (opt-level=3) using pinned Rust 1.98.1. The freshly configured libtiff 4.7.1 reference uses its normal GCC -g -O2 build; both C consumers use -O3. Reference codecs: libjpeg-turbo 3.1.1, libwebp 1.6.0, Zstandard 1.5.7, LERC 4.0.0, and runtime zlib 1.3. libdeflate is disabled. JPEG SIMD is disabled in this pinned test reference; this is not a SIMD-enabled production JPEG comparison. Configure/build logs, dynamic linkage, and binary hashes are retained.',
 'Adapter limits are explicitly raised: 16 GiB file size, 1 GiB output and single-allocation limits, 2 GiB cumulative allocation allowance, and 10^12 work units. These are performance measurements with adequate quotas, not measurements of default deployment limits. The production adapter and core are unchanged and their hashes match the prior reader delivery and its 1,631-obligation proof record. No new full proof run is claimed for this benchmark-only change.',
 'Most generated images are 1024 × 1024, with 64-row strips or 128 × 128 tiles. Patterns include smooth blocks, seeded random bytes, and a synthetic document. Large-strip inputs are 4096 × 4096. Three original libtiff corpus files cover a 24.3 MP LZW scan, an 8.3 MP fax scan, and legacy LZW. The metadata fixture has 200,000 strips. This selected suite is not a representative application workload survey; geometric means weight each listed workload equally. They are not whole-application performance or coverage certification.'
]
findings=[
 'Streaming threshold: with identical RGB pixels, 16-row (48 KiB decoded) Deflate strips take 11.15 ms, while 32-row (96 KiB) strips take 111.17 ms in the verified reader. libtiff takes 1.53 and 1.31 ms. Source inspection confirms native_range selects the streaming path when either decoded or compressed segment size exceeds 64 KiB. This isolates a roughly 10× slowdown at the path change; compression layout still differs, so it is not a single-instruction causal experiment.',
 'Deflate profile: 50.0% of flat CPU samples are in native_stream::Inflater::step, 43.5% in stream::Stream::pull, and 5.0% in Input::ensure. The implementation validates the complete compressed segment before exposing requested bytes, then resumes a second decode. That policy explains why a first-row request can incur full-segment work: the 16 MP Deflate case is 304.64 ms versus 0.0203 ms. These first-row operations produce the same row but do not promise identical validation of unseen data.',
 'LERC profile: 70.1% of samples are in lerc_numeric::pack and 20.4% in lerc_numeric::narrow. These software floating-point reconstruction/conversion routines dominate the plain float32 LERC case, which is 182.2× slower. Deflate/ZSTD-wrapped LERC remains 125.5×/130.7× slower. Those percentages are flat self samples, including inlined code and warm-up, not a call graph or proof that a proposed optimization will recover the entire gap.',
 'RGBA profile: uncompressed RGB spends 78.3% of samples in Handle::rgba and 18.0% in native_samples::read_word. Its native read is 0.191 ms, while full RGBA is 19.06 ms; libtiff RGBA is 0.755 ms. The general per-pixel conversion loop is expensive even when decompression is absent. Full RGBA also retains an internal result in addition to the caller buffer, visible in the large-scan RSS measurements.',
 'Partial-read tradeoff: disabling strip chopping makes the 16 MP uncompressed crop appear 73.1× faster, but ordinary libtiff strip chopping reverses that result: verified 0.195 ms versus libtiff 0.0260 ms (7.5× slower), with 1.75 versus 2.28 MiB RSS. In the same default-mode follow-up, LZW and Deflate crops retain small memory footprints (1.93 and 1.96 MiB versus 23.59 and 18.41 MiB) but take 14.2× and 121.1× as long. Lower memory usage does not imply lower latency.',
 'Metadata: opening the 200,000-strip file takes 1.82 µs versus 1,080 µs in ordinary rmc mode. Enabling libtiff deferred metadata (rmOc) reduces its open to 5.05 µs, so the corresponding verified 1.87 µs open is 2.7× faster. Looking up the last strip offset remains 2.24 µs versus 889.7 µs with that option. Both ordinary and deferred-mode results are included; the large ordinary-open advantage should not be generalized to optimized libtiff users.'
]
commands='''python3 scripts/bootstrap.py
python3 scripts/upstream.py
python3 benchmarks/prepare-reader.py
bash scripts/build-compat.sh
bash benchmarks/build-reader.sh
python3 benchmarks/reader-bench.py --generate-only
python3 benchmarks/reader-bench.py --rounds 7 --milliseconds 100
python3 benchmarks/reader-layout.py
python3 benchmarks/reader-defaults.py
# Optional diagnostic profiling; never use profiled timings as benchmark results:
python3 benchmarks/profile.py --output target/reader-benchmark/profile-lerc.json target/reader-benchmark/verified target/reader-benchmark/inputs/lerc-float-plain.tif native 4000 memory
python3 benchmarks/profile.py --output target/reader-benchmark/profile-deflate.json target/reader-benchmark/verified target/reader-benchmark/inputs/rgb-deflate.tif native 4000 memory
python3 benchmarks/profile.py --output target/reader-benchmark/profile-rgba.json target/reader-benchmark/verified target/reader-benchmark/inputs/rgb-none.tif rgba 4000 memory'''
captions={'defaults':['Input','Operation','Verified ms','4.7.1 ms','Relative time','Verified RSS MiB','4.7.1 RSS MiB'],'summary':['API workload group','Cases','Geometric mean relative time'],'selected':['Input','Operation','Verified ms','4.7.1 ms','Relative time'],'layout':['Rows / strip','Decoded KiB / strip','Operation','Verified ms','4.7.1 ms','Relative time'],'memory':['Input','Operation','Verified RSS MiB','4.7.1 RSS MiB']}
md='# Current verified-tiff versus libtiff 4.7.1\n\n'+intro+'\n\n'+scope+'\n\n## Main suite: fixed file layouts\n\nThe main suite disables automatic strip chopping for both engines. Default-mode partial reads are measured separately below.\n\n'+table(captions['summary'],summary)+'\n## Selected workloads\n\nAll times are medians in milliseconds; relative time is verified / libtiff.\n\n'+table(captions['selected'],representative)+'\n## Bottlenecks and tradeoffs\n\n'+'\n\n'.join(findings)+'\n\n## Controlled strip-height sweep\n\n'+table(captions['layout'],layoutrows)+'\nThe sweep is excluded from the main-suite geometric means. Every layout decoded to the same native output hash.\n\n## Default strip chopping\n\nThese six follow-up workloads use ordinary `rm` opening instead of `rmc`; mmap stays disabled. The same libraries and outputs are used. Derived consumer source, exact one-string change, commands and binary hashes are recorded. Results are excluded from the main geometric means.\n\n'+table(captions['defaults'],defaultrows)+'\n## Peak process memory (main suite, chopping disabled)\n\n'+table(captions['memory'],memory)+'\n## Method and limits\n\n'+'\n\n'.join(methods)+'\n\n## Reproduce\n\n```bash\n'+commands+'\n```\n\nRecorded evidence is in `docs/evidence/reader-benchmark/`: raw samples, input hashes, source/binary hashes, build logs, profiles, and CSV. Fresh runs write to `target/reader-benchmark/` and do not overwrite the recorded evidence. Use `--validate-only` for correctness preflight, or `--resume` only with unchanged binaries and settings. The original source archive hash in the results identifies the pre-benchmark delivery; this delivery adds harnesses and evidence without changing production code.\n\n## Every workload\n\nIQR is the 25th–75th percentile across seven process batches. RSS is from three independent file-backed processes.\n\n'+table(headers,allrows)
(ROOT/'docs/reader-benchmark.md').write_text(md)
with (a.evidence/'results.csv').open('w',newline='') as f:
 w=csv.writer(f);w.writerow(['case','mode','verified_median_ms','libtiff_median_ms','verified_over_libtiff','verified_q1_ms','verified_q3_ms','libtiff_q1_ms','libtiff_q3_ms','verified_peak_rss_mib','libtiff_peak_rss_mib'])
 for r in records:
  v=r['statistics']['verified'];b=r['statistics']['libtiff'];w.writerow([r['case']['name'],r['mode'],v['median_ms'],b['median_ms'],r['ratio'],v['q1_ms'],v['q3_ms'],b['q1_ms'],b['q3_ms'],v['median_rss_mib'],b['median_rss_mib']])
esc=html.escape
css='''*{box-sizing:border-box}body{margin:0;background:#f5f7fa;color:#142438;font:16px/1.6 system-ui,sans-serif}main{max-width:1180px;margin:auto;padding:48px 28px 80px}h1{font-size:clamp(30px,4vw,48px);line-height:1.12;max-width:850px;letter-spacing:-1.5px}h2{font-size:24px;line-height:1.3;margin:42px 0 14px}p{max-width:980px}header>p{font-size:18px}.eyebrow{color:#42677d;font-size:13px;letter-spacing:1.5px;font-weight:700;text-transform:uppercase}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin:26px 0}.card{background:#fff;border:1px solid #dce3eb;border-radius:12px;padding:20px}.card strong{display:block;color:#a2392b;font-size:38px}.card span{font-size:14px;color:#4c6072}.scroll{overflow:auto;background:#fff;border:1px solid #dce3eb;border-radius:10px}table{border-collapse:collapse;width:100%;font-size:13px;font-variant-numeric:tabular-nums}th,td{padding:12px 14px;text-align:right;border-bottom:1px solid #e7ecf1;white-space:nowrap}th:first-child,td:first-child{text-align:left}th{background:#eaf0f6;color:#26475e;position:sticky;top:0}tbody tr:hover{background:#f4f8fb}tbody tr:last-child td{border-bottom:0}.muted{color:#53697a;font-size:14px}.controls{display:flex;gap:10px;flex-wrap:wrap;margin:15px 0}input,select,button{font:inherit;padding:9px 12px;border:1px solid #b6c7d5;border-radius:7px;background:white;color:#17374d}button{cursor:pointer}input{min-width:250px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#152b40;color:#e1edf6;padding:22px;border-radius:10px;font-size:12px}details{margin:18px 0}summary{cursor:pointer;font-weight:700;color:#28576f}.finding{border-left:3px solid #6692a9;padding-left:18px}footer{border-top:1px solid #d5dfe8;margin-top:44px;padding-top:20px;color:#53697a;font-size:13px}@media(max-width:650px){main{padding:28px 16px}.cards{grid-template-columns:1fr}.card strong{font-size:30px}h1{letter-spacing:-.8px}}'''
body='<header><div class="eyebrow">Reader performance · 15 October 2026</div><h1>Current verified-tiff<br>vs. libtiff 4.7.1</h1><p>'+esc(intro)+'</p></header><div class="cards"><div class="card"><strong>13.3×</strong><span>Native read time · 30 workloads</span></div><div class="card"><strong>17.7×</strong><span>RGBA read time · 22 workloads</span></div><div class="card"><strong style="color:#215f71">78 / 78</strong><span>Output checks passed</span></div></div><p class="muted">'+esc(scope)+'</p>'
body+='<h2>Main suite: fixed file layouts</h2>'+htable(captions['summary'],summary)+'<p class="muted">The main suite disables automatic strip chopping. Default-mode partial reads are measured below. Geometric means describe only this chosen suite; no deployment weighting is implied.</p><h2>Selected workloads</h2>'+htable(captions['selected'],representative)
body+='<h2>Where the time goes</h2>'+''.join('<p class="finding">'+esc(t)+'</p>' for t in findings)
body+='<h2>Same pixels, different strip sizes</h2>'+htable(captions['layout'],layoutrows)+'<p class="muted">Separate diagnostic sweep; excluded from suite summaries. All four layouts produced identical native pixels.</p><h2>Default strip chopping</h2><p>Ordinary rm opening keeps mmap disabled and enables default strip chopping. These six supplementary workloads use the same libraries and return the same outputs. Their derived consumer source changes only the open-mode string. They are excluded from the main geometric means.</p>'+htable(captions['defaults'],defaultrows)+'<h2>Peak process memory (main suite)</h2>'+htable(captions['memory'],memory)
body+='<h2>Method and limits</h2>'+''.join('<p>'+esc(t)+'</p>' for t in methods)+'<details><summary>Reproduction commands</summary><pre>'+esc(commands)+'</pre><p>Raw recorded evidence is in docs/evidence/reader-benchmark/ inside the source archive. Fresh runs write to target/reader-benchmark/. The decoder and adapter sources are unchanged.</p></details>'
body+='<h2>All 78 workloads</h2><p class="muted">Times are milliseconds. IQR is the middle 50% of seven batches. RSS is the median peak process footprint from three independent file-backed runs.</p><div class="controls"><input id="search" aria-label="Filter workloads" placeholder="Filter workload name…"><select id="mode" aria-label="Operation"><option value="">All operations</option>'+''.join('<option>'+esc(m)+'</option>' for m in sorted({r['mode'] for r in records}))+'</select><button id="raw">Download raw JSON</button><button id="csv">Download CSV</button></div><p id="count" class="muted">78 workloads</p>'+htable(headers,allrows,'all')
body+='<footer>Freshly built libraries · same C API consumer · unchanged production sources · AMD EPYC 9V74 · single logical CPU · shared virtual host. Source, input, and binary SHA-256 hashes are retained in the embedded raw results and the source archive.</footer>'
js='''const data=JSON.parse(document.getElementById('data').textContent);const rows=[...document.querySelectorAll('#all tbody tr')];function filter(){const q=document.getElementById('search').value.toLowerCase(),m=document.getElementById('mode').value;let n=0;rows.forEach(r=>{const yes=r.cells[0].textContent.toLowerCase().includes(q)&&(!m||r.cells[1].textContent===m);r.hidden=!yes;n+=yes});document.getElementById('count').textContent=n+' workloads'}document.getElementById('search').addEventListener('input',filter);document.getElementById('mode').addEventListener('change',filter);function download(text,type,name){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}document.getElementById('raw').onclick=()=>download(JSON.stringify(data,null,2),'application/json','reader-benchmark-results.json');document.getElementById('csv').onclick=()=>{const h=['case','mode','verified_ms','libtiff_ms','verified_over_libtiff','verified_rss_mib','libtiff_rss_mib'];const values=data.main.records.map(r=>[r.case.name,r.mode,r.statistics.verified.median_ms,r.statistics.libtiff.median_ms,r.ratio,r.statistics.verified.median_rss_mib,r.statistics.libtiff.median_rss_mib]);download([h,...values].map(r=>r.map(v=>JSON.stringify(v)).join(',')).join('\\n'),'text/csv','reader-benchmark.csv')};'''
embedded=json.dumps({'main':data,'layout':layout,'defaults':defaults},separators=(',',':')).replace('</',r'<\/')
a.html.parent.mkdir(parents=True,exist_ok=True);a.html.write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>verified-tiff vs libtiff 4.7.1 — reader benchmark</title><style>'+css+'</style></head><body><main>'+body+'</main><script id="data" type="application/json">'+embedded+'</script><script>'+js+'</script></body></html>')
print(a.html);print(ROOT/'docs/reader-benchmark.md')
